script:
function run(input, resume, ctx) {
  var r = ctx.http.request({effect_id: "source-download-v1", url: input.url,
    method: "GET", replay: "safe", response: {mode: "artifact", name: "source.bin"}});
  ctx.checkpoint({download: r.artifact});
  ctx.progress({bytes: r.artifact.length});
  return {download: r.artifact, status: r.status};
}
